from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        self._purchases = {}  # customer -> list of (available_date, points)
        self._redemptions = {}  # customer -> list of (day, points)

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount // 10)
        available_date = day + timedelta(days=14)
        self._purchases.setdefault(customer, []).append((available_date, points))
        return points

    def _available(self, customer: str, day: date) -> int:
        earned = sum(p for avail, p in self._purchases.get(customer, []) if avail <= day)
        spent = sum(p for d, p in self._redemptions.get(customer, []) if d <= day)
        return earned - spent

    def balance(self, customer: str, day: date) -> int:
        return self._available(customer, day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0:
            raise ValueError("Redemption points must be positive")
        if points > self._available(customer, day):
            raise ValueError("Insufficient available points")
        self._redemptions.setdefault(customer, []).append((day, points))
